 @Autowired FairService fairs;@Autowired @Qualifier("empresasJdbcTemplate")JdbcTemplate emp;@Autowired @Qualifier("jdbcTemplate")JdbcTemplate opp;@Autowired @Qualifier("capacitaJdbcTemplate")JdbcTemplate cap;
 @Autowired @Qualifier("candidateFairRegistrations")FairRegistrationStore candidates;@Autowired @Qualifier("studentFairRegistrations")FairRegistrationStore students;@Autowired RadarBridge bridge;@Autowired HubLearningController publicCourses;@Autowired TerritorialCatalog geo;@Autowired WebApplicationContext context;@Autowired TrailTokenService tokens;
 com.sun.net.httpserver.HttpServer server;Object oldBase,oldSecret;AtomicBoolean sourceDown=new AtomicBoolean(),coursesDown=new AtomicBoolean();List<String> outgoing=new CopyOnWriteArrayList<>();
 record User(long id,String email){} record Org(long id,User manager){} record Company(long id,User owner,long job){}
 @BeforeEach void source()throws Exception{oldBase=ReflectionTestUtils.getField(bridge,"base");oldSecret=ReflectionTestUtils.getField(bridge,"secret");server=com.sun.net.httpserver.HttpServer.create(new java.net.InetSocketAddress("127.0.0.1",0),0);server.createContext("/api/",exchange->{int code=200;Object value;try{if(sourceDown.get())throw new ResponseStatusException(org.springframework.http.HttpStatus.SERVICE_UNAVAILABLE);String path=exchange.getRequestURI().getPath();assertNull(exchange.getRequestHeaders().getFirst("Authorization"));if(path.startsWith("/api/public/job-fairs/"))value=fairs.publicEvent(Long.parseLong(path.substring(path.lastIndexOf('/')+1)));else if(path.startsWith("/api/public/capacita/hub/courses/")){if(coursesDown.get())throw new ResponseStatusException(org.springframework.http.HttpStatus.SERVICE_UNAVAILABLE);value=publicCourses.course(Long.parseLong(path.substring(path.lastIndexOf('/')+1)));}else if(path.endsWith("/counts")){bridge.authorize(exchange.getRequestHeaders().getFirst("X-Trampolim-Bridge"));String raw=new String(exchange.getRequestBody().readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);outgoing.add(raw);var query=bridge.convert(bridge.read(raw),CountQuery.class);value=path.contains("/opportunities/")?candidates.counts(query):students.counts(query);}else throw new ResponseStatusException(org.springframework.http.HttpStatus.NOT_FOUND);}catch(ResponseStatusException e){code=e.getStatusCode().value();value=Map.of("detail","Synthetic source response");}catch(Exception e){code=500;value=Map.of("detail","Synthetic handler failure");}byte[] bytes=bridge.encode(value).getBytes(java.nio.charset.StandardCharsets.UTF_8);exchange.getResponseHeaders().set("Content-Type","application/json");exchange.sendResponseHeaders(code,bytes.length);exchange.getResponseBody().write(bytes);exchange.close();});ReflectionTestUtils.setField(bridge,"base","http://127.0.0.1:"+server.getAddress().getPort()+"/api");ReflectionTestUtils.setField(bridge,"secret","synthetic-fair-bridge-secret-00000000000000");server.start();}
 @AfterEach void restore(){server.stop(0);ReflectionTestUtils.setField(bridge,"base",oldBase);ReflectionTestUtils.setField(bridge,"secret",oldSecret);}
 User user(JdbcTemplate db,String trail){return user(db,trail,UUID.randomUUID()+"@example.test");}
 User user(JdbcTemplate db,String trail,String email){String sql=trail.equals("EMPRESAS")?"INSERT INTO company_users(email,password_hash,full_name,email_verified,account_status) VALUES (?,'fixture','Pessoa sintética',TRUE,'ACTIVE') RETURNING id":trail.equals("CAPACITA")?"INSERT INTO student_users(email,password_hash,full_name,email_verified,account_status,education_stage,terms_accepted_at) VALUES (?,'fixture','Pessoa sintética',TRUE,'ACTIVE','HIGH_SCHOOL',CURRENT_TIMESTAMP) RETURNING id":"INSERT INTO app_users(email,password_hash,full_name,email_verified,account_type) VALUES (?,'fixture','Pessoa sintética',TRUE,'PERSON') RETURNING id";return new User(db.queryForObject(sql,Long.class,email),email);}
 Org org(){var manager=user(emp,"EMPRESAS");long id=emp.queryForObject("INSERT INTO enterprise_organizations(name,organization_type,status) VALUES (?,'ASSOCIATION','ACTIVE') RETURNING id",Long.class,"Associação sintética "+UUID.randomUUID());emp.update("INSERT INTO enterprise_organization_members(organization_id,email,full_name,role) VALUES (?,?,'Gestor sintético','ASSOCIATION_ADMIN')",id,manager.email());emp.update("UPDATE hub_profiles SET published=TRUE WHERE organization_id=?",id);return new Org(id,manager);}
 Company company(Org org){var owner=user(emp,"EMPRESAS");String cnpj=String.format("%014d",Math.abs(UUID.randomUUID().getLeastSignificantBits()%100000000000000L));long c=emp.queryForObject("INSERT INTO companies(owner_user_id,legal_name,trade_name,cnpj,phone,industry,address,city,state,verification_status) VALUES (?,'Empresa sintética','Empresa sintética',?,'fixture','fixture','fixture','Irecê','BA','APPROVED') RETURNING id",Long.class,owner.id(),cnpj);emp.update("INSERT INTO enterprise_organization_companies(organization_id,company_id,relationship_type,status) VALUES (?,?,'ASSOCIATION_MEMBER','ACTIVE')",org.id(),c);long job=emp.queryForObject("INSERT INTO company_listings(company_id,kind,title,area,description,requirements,location,modality,url,contact_email,payment_status,publication_status) VALUES (?,'job','Vaga sintética','Tecnologia','Fixture','Fixture','Irecê','Remoto','https://example.test','fixture@example.test','NOT_PROCESSED','PUBLISHED') RETURNING id",Long.class,c);return new Company(c,owner,job);}
 Definition definition(String mode,String city,long revision,UUID key){return new Definition("Feirão sintético "+key,"Evento isolado para teste",Instant.now().plus(Duration.ofDays(1)).toString(),Instant.now().plus(Duration.ofDays(2)).toString(),mode,city,mode.equals("DIGITAL")?"":"Local sintético",true,null,revision,key);}
 long create(Org o){return number(fairs.create(o.manager().email(),o.id(),definition("DIGITAL","2914604",0,UUID.randomUUID())),"id");}
 long revision(Org o,long id){return number(fairs.detail(o.manager().email(),o.id(),id),"revision");}
 void publish(Org o,long id){fairs.publish(o.manager().email(),o.id(),id,new Publication("PUBLISHED",revision(o,id)));}
 void accepted(Org o,long id,Company c){fairs.invite(o.manager().email(),o.id(),id,new Reference(c.id(),revision(o,id)));fairs.companyDecision(c.owner().email(),id,new CompanyDecision(true,0));}
 List<?> items(Map<String,Object> value){return (List<?>)value.get("items");}
 void code(int expected,Runnable action){assertEquals(expected,assertThrows(ResponseStatusException.class,action::run).getStatusCode().value());}
 long course(){var teacher=user(cap,"CAPACITA");cap.update("INSERT INTO learning_account_roles(user_id,role) VALUES (?,'TEACHER')",teacher.id());return cap.queryForObject("INSERT INTO learning_courses(teacher_id,title,description,category,status) VALUES (?,'Curso sintético existente','Fixture','Teste','PUBLISHED') RETURNING id",Long.class,teacher.id());}
 @Test void draftsAreIdempotentAndNeverCreateFakeCompaniesOrJobs(){var o=org();var input=definition("DIGITAL","",0,UUID.randomUUID());long companies=emp.queryForObject("SELECT count(*) FROM companies",Long.class),jobs=emp.queryForObject("SELECT count(*) FROM company_listings",Long.class);var first=fairs.create(o.manager().email(),o.id(),input);long id=number(first,"id");assertEquals(id,number(fairs.create(o.manager().email(),o.id(),input),"id"));code(404,()->fairs.publicEvent(id));assertEquals(companies,emp.queryForObject("SELECT count(*) FROM companies",Long.class));assertEquals(jobs,emp.queryForObject("SELECT count(*) FROM company_listings",Long.class));var wrong=new Definition("Outro título",input.description(),input.startsAt(),input.endsAt(),input.modality(),input.municipalityCode(),input.venue(),true,null,0,input.requestKey());code(409,()->fairs.create(o.manager().email(),o.id(),wrong));}
 @Test void filtersAndPaginationSupportOtherMunicipalitiesAndAllModes(){var o=org();String suffix=UUID.randomUUID().toString();for(String mode:List.of("PRESENCIAL","DIGITAL","HIBRIDO")){var raw=definition(mode,"2914604",0,UUID.randomUUID());var def=new Definition(suffix,raw.description(),raw.startsAt(),raw.endsAt(),mode,raw.municipalityCode(),raw.venue(),true,null,0,raw.requestKey());long id=number(fairs.create(o.manager().email(),o.id(),def),"id");publish(o,id);}assertEquals(3,items(fairs.publicList(Long.MAX_VALUE,20,suffix,"","2914604","BA","","","",false)).size());assertEquals(1,items(fairs.publicList(Long.MAX_VALUE,20,suffix,"","","","HIBRIDO","","",false)).size());var first=fairs.publicList(Long.MAX_VALUE,2,suffix,"","","","","","",false);assertEquals(2,items(first).size());assertEquals(1,items(fairs.publicList(((Number)first.get("nextCursor")).longValue(),2,suffix,"","","","","","",false)).size());String sp=geo.search("São Paulo","SP",50).stream().filter(c->c.name().equals("São Paulo")).findFirst().orElseThrow().code();long elsewhere=number(fairs.create(o.manager().email(),o.id(),definition("PRESENCIAL",sp,0,UUID.randomUUID())),"id");publish(o,elsewhere);assertEquals("SP",fairs.publicEvent(elsewhere).get("state"));code(400,()->fairs.publicList(Long.MAX_VALUE,51,"","","","","","","",false));}
 @Test void organizationPermissionsAndCampaignScopeAreEnforced(){var a=org();var b=org();long id=create(a);code(403,()->fairs.detail(b.manager().email(),a.id(),id));code(404,()->fairs.detail(b.manager().email(),b.id(),id));var member=user(emp,"EMPRESAS");emp.update("INSERT INTO enterprise_organization_members(organization_id,email,full_name,role) VALUES (?,?,'Leitor sintético','ASSOCIATION_MEMBER')",a.id(),member.email());assertEquals(id,number(fairs.detail(member.email(),a.id(),id),"id"));code(403,()->fairs.publish(member.email(),a.id(),id,new Publication("PUBLISHED",1)));long campaign=emp.queryForObject("INSERT INTO hub_campaigns(organization_id,title,body,starts_on,ends_on,status) VALUES (?,'Campanha existente','Fixture',CURRENT_DATE,CURRENT_DATE+10,'PUBLISHED') RETURNING id",Long.class,b.id());var raw=definition("DIGITAL","",0,UUID.randomUUID());code(400,()->fairs.create(a.manager().email(),a.id(),new Definition(raw.title(),raw.description(),raw.startsAt(),raw.endsAt(),raw.modality(),"","",true,campaign,0,raw.requestKey())));emp.update("UPDATE hub_campaigns SET organization_id=? WHERE id=?",a.id(),campaign);long linked=number(fairs.create(a.manager().email(),a.id(),new Definition(raw.title(),raw.description(),raw.startsAt(),raw.endsAt(),raw.modality(),"","",true,campaign,0,raw.requestKey())),"id");publish(a,linked);emp.update("UPDATE hub_campaigns SET status='ARCHIVED' WHERE id=?",campaign);code(404,()->fairs.publicEvent(linked));}
 @Test void publicVacanciesRequireCompanyConfirmationAndExistingPaymentRules(){var o=org();long id=create(o);var c=company(o);code(400,()->fairs.linkJob(o.manager().email(),o.id(),id,new Reference(c.job(),revision(o,id))));accepted(o,id,c);fairs.linkJob(o.manager().email(),o.id(),id,new Reference(c.job(),revision(o,id)));fairs.linkJob(o.manager().email(),o.id(),id,new Reference(c.job(),revision(o,id)));assertEquals(1,emp.queryForObject("SELECT count(*) FROM job_fair_listings WHERE event_id=?",Integer.class,id));publish(o,id);assertEquals(1,items(fairs.publicJobs(id,Long.MAX_VALUE,20,"","")).size());emp.update("UPDATE company_listings SET is_internship=TRUE,payment_status='PENDING' WHERE id=?",c.job());assertTrue(items(fairs.publicJobs(id,Long.MAX_VALUE,20,"","")).isEmpty());code(400,()->fairs.linkJob(o.manager().email(),o.id(),id,new Reference(c.job(),revision(o,id))));emp.update("UPDATE company_listings SET payment_status='PAID' WHERE id=?",c.job());assertEquals(1,items(fairs.publicJobs(id,Long.MAX_VALUE,20,"","")).size());emp.update("UPDATE company_listings SET expires_at=CURRENT_DATE-1 WHERE id=?",c.job());assertTrue(items(fairs.publicJobs(id,Long.MAX_VALUE,20,"","")).isEmpty());assertEquals("PUBLISHED",emp.queryForObject("SELECT publication_status FROM company_listings WHERE id=?",String.class,c.job()));}
 @Test void withdrawalAndMembershipChangesHideLinksWithoutMutatingOriginalJobs(){var o=org();long id=create(o);var c=company(o);accepted(o,id,c);fairs.linkJob(o.manager().email(),o.id(),id,new Reference(c.job(),revision(o,id)));publish(o,id);fairs.companyDecision(c.owner().email(),id,new CompanyDecision(false,1));assertTrue(items(fairs.publicJobs(id,Long.MAX_VALUE,20,"","")).isEmpty());code(409,()->fairs.companyDecision(c.owner().email(),id,new CompanyDecision(true,2)));fairs.invite(o.manager().email(),o.id(),id,new Reference(c.id(),revision(o,id)));fairs.companyDecision(c.owner().email(),id,new CompanyDecision(true,3));emp.update("UPDATE enterprise_organization_companies SET status='ENDED' WHERE organization_id=? AND company_id=?",o.id(),c.id());assertTrue(items(fairs.publicCompanies(id,Long.MAX_VALUE,20)).isEmpty());assertTrue(items(fairs.publicJobs(id,Long.MAX_VALUE,20,"","")).isEmpty());assertEquals(1,emp.queryForObject("SELECT count(*) FROM company_listings WHERE id=?",Integer.class,c.job()));}
 @Test void publicCoursesUseHttpAndAreRevalidatedWhenHiddenOrUnavailable(){var o=org();long id=create(o),course=course();fairs.linkCourse(o.manager().email(),o.id(),id,new Reference(course,revision(o,id)));publish(o,id);assertEquals(1,items(fairs.publicCourses(id,Long.MAX_VALUE,20)).size());cap.update("UPDATE learning_courses SET status='HIDDEN' WHERE id=?",course);assertTrue(items(fairs.publicCourses(id,Long.MAX_VALUE,20)).isEmpty());coursesDown.set(true);assertEquals("UNAVAILABLE",fairs.publicCourses(id,Long.MAX_VALUE,20).get("sourceStatus"));assertEquals(1,cap.queryForObject("SELECT count(*) FROM learning_courses WHERE id=?",Integer.class,course));}
 @Test void agendaRequiresPublicConsentAndValidTimes(){var o=org();long id=create(o);var e=fairs.detail(o.manager().email(),o.id(),id);String from=time(e.get("starts_at")).plusSeconds(60).toString(),to=time(e.get("starts_at")).plusSeconds(120).toString();code(400,()->fairs.session(o.manager().email(),o.id(),id,0,new Session("TALK","Palestra sintética","Fixture","Pessoa",false,from,to,revision(o,id))));fairs.session(o.manager().email(),o.id(),id,0,new Session("TALK","Palestra sintética","Fixture","Pessoa autorizada",true,from,to,revision(o,id)));code(400,()->fairs.session(o.manager().email(),o.id(),id,0,new Session("WORKSHOP","Teste","Fixture","",false,from,time(e.get("ends_at")).plusSeconds(1).toString(),revision(o,id))));publish(o,id);assertEquals(1,items(fairs.sessions(null,0,id,Long.MAX_VALUE,20,true)).size());code(409,()->fairs.update(o.manager().email(),o.id(),id,definition("DIGITAL","",revision(o,id),UUID.randomUUID())));}
 @Test void cancelledAndExpiredEventsDoNotOfferOpenRegistrationsOrJobs(){var o=org();long id=create(o);publish(o,id);fairs.publish(o.manager().email(),o.id(),id,new Publication("CANCELLED",revision(o,id)));assertEquals("CANCELLED",fairs.publicEvent(id).get("phase"));assertEquals(false,fairs.publicEvent(id).get("registrationOpen"));code(409,()->fairs.publicJobs(id,Long.MAX_VALUE,20,"",""));long ended=create(o);publish(o,ended);emp.update("UPDATE job_fairs SET starts_at=CURRENT_TIMESTAMP-INTERVAL '2 days',ends_at=CURRENT_TIMESTAMP-INTERVAL '1 day' WHERE id=?",ended);assertEquals("ENDED",fairs.publicEvent(ended).get("phase"));assertEquals(false,fairs.publicEvent(ended).get("registrationOpen"));}
 @Test void registrationsStayIndependentAndIndicatorsNeverExposePeople(){var o=org();long id=create(o);publish(o,id);String email=UUID.randomUUID()+"@example.test";var candidate=user(opp,"OPORTUNIDADES",email);var student=user(cap,"CAPACITA",email);code(400,()->candidates.join(candidate.email(),id,new Registration(false,0,UUID.randomUUID())));var input=new Registration(true,0,UUID.randomUUID());var first=candidates.join(candidate.email(),id,input);assertEquals(first.get("receipt"),candidates.join(candidate.email(),id,input).get("receipt"));students.join(student.email(),id,new Registration(true,0,UUID.randomUUID()));assertEquals(1,opp.queryForObject("SELECT count(*) FROM job_fair_registrations WHERE user_id=?",Integer.class,candidate.id()));assertEquals(1,cap.queryForObject("SELECT count(*) FROM job_fair_registrations WHERE user_id=?",Integer.class,student.id()));assertEquals(2L,fairs.indicators(o.manager().email(),o.id(),id).get("registeredAccountsTotal"));assertFalse(outgoing.toString().contains(email));sourceDown.set(true);assertNull(fairs.indicators(o.manager().email(),o.id(),id).get("registeredAccountsTotal"));candidates.withdraw(candidate.email(),id,1);assertEquals("WITHDRAWN",opp.queryForObject("SELECT status FROM job_fair_registrations WHERE user_id=?",String.class,candidate.id()));}
 @Test void anotherUserCannotReadARegistrationAndOldRetriesCannotReenroll(){var o=org();long id=create(o);publish(o,id);var a=user(opp,"OPORTUNIDADES");var b=user(opp,"OPORTUNIDADES");var input=new Registration(true,0,UUID.randomUUID());candidates.join(a.email(),id,input);assertTrue(items(candidates.list(b.email(),Long.MAX_VALUE,20)).isEmpty());assertEquals(false,candidates.get(b.email(),id).get("exists"));candidates.withdraw(a.email(),id,1);code(409,()->candidates.join(a.email(),id,input));candidates.join(a.email(),id,new Registration(true,2,UUID.randomUUID()));assertEquals(3L,number(candidates.get(a.email(),id),"revision"));}
 @Test void concurrentEditsUseOneRevision()throws Exception{var o=org();long id=create(o),version=revision(o,id);try(var pool=Executors.newFixedThreadPool(2)){var start=new CountDownLatch(1);var futures=new ArrayList<Future<Integer>>();for(int i=0;i<2;i++)futures.add(pool.submit(()->{start.await();try{fairs.update(o.manager().email(),o.id(),id,definition("DIGITAL","",version,UUID.randomUUID()));return 200;}catch(ResponseStatusException e){return e.getStatusCode().value();}}));start.countDown();var result=new ArrayList<Integer>();for(var future:futures)result.add(future.get(15,TimeUnit.SECONDS));Collections.sort(result);assertEquals(List.of(200,409),result);assertEquals(version+1,revision(o,id));}}
 @Test void endpointsRejectCrossTrailTokensAndUnauthenticatedAggregation()throws Exception{var o=org();long id=create(o);var person=user(opp,"OPORTUNIDADES");var student=user(cap,"CAPACITA");var mvc=MockMvcBuilders.webAppContextSetup(context).apply(SecurityMockMvcConfigurers.springSecurity()).build();String corp=tokens.issue(TrailTokenService.Trail.EMPRESAS,o.manager().email(),o.manager().id(),0),candidate=tokens.issue(TrailTokenService.Trail.OPORTUNIDADES,person.email(),person.id(),0),school=tokens.issue(TrailTokenService.Trail.CAPACITA,student.email(),student.id(),0);mvc.perform(get("/api/empresas/hub/organizations/"+o.id()+"/job-fairs/"+id).header("Authorization","Bearer "+corp)).andExpect(status().isOk());for(String wrong:List.of(candidate,school)){int code=mvc.perform(get("/api/empresas/hub/organizations/"+o.id()+"/job-fairs/"+id).header("Authorization","Bearer "+wrong)).andReturn().getResponse().getStatus();assertTrue(Set.of(401,403).contains(code));}mvc.perform(get("/api/public/job-fairs/"+id)).andExpect(status().isNotFound());publish(o,id);mvc.perform(get("/api/public/job-fairs/"+id)).andExpect(status().isOk()).andExpect(jsonPath("$.registrationOpen").value(true));mvc.perform(put("/api/job-fairs/"+id+"/registration").header("Authorization","Bearer "+candidate).contentType(MediaType.APPLICATION_JSON).content(bridge.encode(new Registration(true,0,UUID.randomUUID())))).andExpect(status().isOk());int wrong=mvc.perform(get("/api/capacita/job-fairs/registrations").header("Authorization","Bearer "+candidate)).andReturn().getResponse().getStatus();assertTrue(Set.of(401,403).contains(wrong));mvc.perform(post("/api/integrations/job-fairs/opportunities/counts").contentType(MediaType.APPLICATION_JSON).content(bridge.encode(new CountQuery(o.id(),List.of(id))))).andExpect(status().isUnauthorized());mvc.perform(post("/api/integrations/job-fairs/opportunities/counts").header("X-Trampolim-Bridge","synthetic-fair-bridge-secret-00000000000000").contentType(MediaType.APPLICATION_JSON).content(bridge.encode(new CountQuery(o.id(),List.of(id))))).andExpect(status().isOk()).andExpect(jsonPath("$.counts."+id).value(1));}

